 <T> void task(String message,Callable<T> call,Result<T> done){int token=++generation;busy=true;notice=message;redraw();a.io.execute(()->{try{T result=call.call();a.ui.post(()->{if(a.dead||token!=generation)return;busy=false;try{done.accept(result);}catch(Exception e){failure(e);}redraw();});}catch(Exception e){a.ui.post(()->{if(a.dead||token!=generation)return;busy=false;failure(e);redraw();});}});}
